71	import { paypalConfigured, createPayPalOrder, capturePayPalOrder } from "./paypal";
72	import { coinbaseConfigured, createCoinbaseCharge } from "./coinbase-commerce";
73	import { fulfilExternalPayment, packExternalPaymentMetadata, type FulfilResult } from "./fulfil-checkout";
74	
75	/** Same window Stripe's card-leg checkout uses for its "abandoned checkout" grace
76	 *  (lib/actions.ts's RESERVATION_GRACE_MS, duplicated here rather than exported
77	 *  out of that file purely to avoid touching it for a constant). PayPal orders and
78	 *  Coinbase charges each have their own, LONGER provider-side expiry (PayPal ~3h,
79	 *  Coinbase Commerce ~1h), so a hold reserved for this long always outlives the
80	 *  window the customer could actually still be paying in. An abandoned hold is
81	 *  never stuck forever regardless: `sweepExpiredReservations` (worker/index.ts)
82	 *  is the same backstop the Stripe path already relies on. */
83	const RESERVATION_GRACE_MS = 10 * 60 * 1000;
84	const PAYPAL_HOLD_MS = 3 * 60 * 60 * 1000 + RESERVATION_GRACE_MS;
85	const COINBASE_HOLD_MS = 60 * 60 * 1000 + RESERVATION_GRACE_MS;
86	
87	function appBase(): string {
88	  return process.env.APP_URL ?? "http://localhost:3000";
89	}
90	
91	// NOTE: whether PayPal/Coinbase are configured is intentionally NOT exposed from
92	// this file. Every export of a "use server" module is a public, network-callable
93	// endpoint (see test/auth-lockouts.test.ts's HAZARD suite) — a plain env-var
94	// read has nothing to authenticate, so it belongs in a plain module instead of
95	// minting an unauthenticated endpoint for no reason. Server components read
96	// `paypalConfigured()` / `coinbaseConfigured()` / `paypalClientIdPublic()`
97	// directly from lib/paypal.ts and `coinbaseConfigured()` from
98	// lib/coinbase-commerce.ts (neither file has "use server") and pass the booleans
99	// down as plain props, the same way `stripeConfigured()` already does.
100	
101	export type CreatePayPalOrderResult = { error: string } | { paypalOrderId: string; pendingId: string };
102	export type CreateCoinbaseChargeResult = { error: string } | { hostedUrl: string; pendingId: string };
103	
104	async function openPayPal(opts: {
105	  userId: string;
106	  kind: string;
107	  amountCents: number;
108	  metadata: Record<string, string>;
109	  description: string;
110	}): Promise<{ error: string } | { paypalOrderId: string; pendingId: string }> {
111	  if (!paypalConfigured()) return { error: "PayPal isn't set up yet — try another payment method." };
112	  // Admin kill switch (/admin/settings → Payments) — checked here too, not just
113	  // in the prop that hides the row client-side, so disabling PayPal actually
114	  // blocks it even if this action is called directly.
115	  if (!(await getSettingBool("payments_paypal_enabled", true))) {
116	    return { error: "PayPal is temporarily unavailable — try another payment method." };
117	  }
118	  const row = await db.pendingExternalPayment.create({
119	    data: {
120	      provider: "paypal",
121	      kind: opts.kind,
122	      userId: opts.userId,
123	      amountCents: opts.amountCents,
124	      currency: "usd",
125	      metadata: JSON.stringify(opts.metadata),
126	    },
127	  });
128	  try {
129	    const order = await createPayPalOrder({ amountCents: opts.amountCents, pendingId: row.id, description: opts.description });
130	    await db.pendingExternalPayment.update({ where: { id: row.id }, data: { providerRef: order.id } }).catch(() => {});
131	    return { paypalOrderId: order.id, pendingId: row.id };
132	  } catch (e) {
133	    await db.pendingExternalPayment.update({ where: { id: row.id }, data: { status: "FAILED" } }).catch(() => {});
134	    console.error("[payments] could not create PayPal order", e);
135	    return { error: "We couldn't start the PayPal payment — please try again." };
136	  }
137	}
