139	async function openCoinbase(opts: {
140	  userId: string;
141	  kind: string;
142	  amountCents: number;
143	  metadata: Record<string, string>;
144	  name: string;
145	  description: string;
146	  redirectPath: string;
147	  cancelPath: string;
148	}): Promise<{ error: string } | { hostedUrl: string; pendingId: string }> {
149	  if (!coinbaseConfigured()) return { error: "Crypto payments aren't set up yet — try another payment method." };
150	  // Admin kill switch (/admin/settings → Payments) — same defense-in-depth as
151	  // openPayPal above.
152	  if (!(await getSettingBool("payments_coinbase_enabled", true))) {
153	    return { error: "Crypto payments are temporarily unavailable — try another payment method." };
154	  }
155	  const row = await db.pendingExternalPayment.create({
156	    data: {
157	      provider: "coinbase",
158	      kind: opts.kind,
159	      userId: opts.userId,
160	      amountCents: opts.amountCents,
161	      currency: "usd",
162	      metadata: JSON.stringify(opts.metadata),
163	    },
164	  });
165	  try {
166	    const charge = await createCoinbaseCharge({
167	      amountCents: opts.amountCents,
168	      pendingId: row.id,
169	      name: opts.name,
170	      description: opts.description,
171	      redirectUrl: `${appBase()}${opts.redirectPath}`,
172	      cancelUrl: `${appBase()}${opts.cancelPath}`,
173	    });
174	    await db.pendingExternalPayment.update({ where: { id: row.id }, data: { providerRef: charge.code } }).catch(() => {});
175	    return { hostedUrl: charge.hosted_url, pendingId: row.id };
176	  } catch (e) {
177	    await db.pendingExternalPayment.update({ where: { id: row.id }, data: { status: "FAILED" } }).catch(() => {});
178	    console.error("[payments] could not create Coinbase Commerce charge", e);
179	    return { error: "We couldn't start the crypto payment — please try again." };
180	  }
181	}
