183	/**
184	 * Capture a PayPal order server-to-server and fulfil it — the PayPal analogue of
185	 * the Stripe confirm route (app/api/stripe/confirm/route.ts). Called from the
186	 * wizard's `onApprove` callback; the PayPal webhook is the reliable backstop for
187	 * the same reason the Stripe webhook is (a closed tab must not be the only thing
188	 * that could have fulfilled a paid order). Idempotent via `fulfilExternalPayment`'s
189	 * FulfilledSession claim, so this racing the webhook is safe.
190	 */
191	export async function captureExternalPayPalOrder(
192	  paypalOrderId: string,
193	  pendingId: string,
194	): Promise<{ redirect?: string; error?: string }> {
195	  const user = await requireUser();
196	  const row = await db.pendingExternalPayment.findUnique({ where: { id: pendingId } });
197	  if (!row || row.userId !== user.id || row.provider !== "paypal") {
198	    return { error: "We couldn't find that payment." };
199	  }
200	
201	  let captured;
202	  try {
203	    captured = await capturePayPalOrder(paypalOrderId);
204	  } catch (e) {
205	    console.error("[payments] PayPal capture failed", paypalOrderId, e);
206	    return { error: "We couldn't confirm that PayPal payment. If you were charged, contact support — your money is safe." };
207	  }
208	  if (captured.status !== "COMPLETED") {
209	    return { error: `PayPal reported this payment as "${captured.status}" — please try again or use another method.` };
210	  }
211	  // Defence in depth: the captured amount must match what we asked PayPal to
212	  // charge. It always will (we set it), but a mismatch here means something is
213	  // wrong enough that fulfilling on trust would be the bug, not the fix.
214	  const capturedCents = Math.round(
215	    Number(captured.purchase_units?.[0]?.payments?.captures?.[0]?.amount?.value ?? "0") * 100,
216	  );
217	  if (capturedCents !== row.amountCents) {
218	    console.error("[payments] PayPal captured amount mismatch", { paypalOrderId, capturedCents, expected: row.amountCents });
219	    return { error: "That payment didn't match the expected amount. Contact support — nothing has been provisioned." };
220	  }
221	
222	  try {
223	    const result: FulfilResult = await fulfilExternalPayment({
224	      provider: "paypal",
225	      externalId: paypalOrderId,
226	      pendingId,
227	      base: appBase(),
228	    });
229	    return { redirect: result.redirect };
230	  } catch (e) {
231	    console.error("[payments] PayPal fulfilment failed", paypalOrderId, e);
232	    return { error: "Your PayPal payment went through but we couldn't finish setup. Contact support — your money is safe and we've been alerted." };
233	  }
234	}
