236	/* ------------------------------------------------------------------ *
237	 * VPS order — mirrors payAndDeploy's quote/promo/coupon/tax path
238	 * (lib/actions.ts) up to the point of opening a payment session.
239	 * ------------------------------------------------------------------ */
240	
241	async function quoteVpsOrderForExternalPayment(formData: FormData): Promise<
242	  | { error: string }
243	  | {
244	      cardCents: number;
245	      metadata: Record<string, string>;
246	      release: () => Promise<void>;
247	    }
248	> {
249	  const user = await requireUser();
250	  await assertNotImpersonating();
251	  const unverified = await emailVerificationError(user);
252	  if (unverified) return { error: unverified };
253	  const limitErr = await serverLimitError(user.id);
254	  if (limitErr) return { error: limitErr };
255	
256	  const intent = intentFromFormData(formData);
257	  intent.partnerSource = partnerSourceFromCookie(await cookies());
258	
259	  let quote;
260	  try {
261	    quote = await orderQuote(intent);
262	  } catch (e) {
263	    if (e instanceof OrderError) return { error: e.message };
264	    throw e;
265	  }
266	
267	  const promoIpHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
268	  if (quote.promoCreditCents > 0 && !(await firstMonthFreeEligible(user.id, promoIpHash))) {
269	    quote = await orderQuote(intent, { suppressPromo: true });
270	  }
271	  const promoCampaign = promoCampaignFromCookie(await cookies());
272	
273	  const useWallet = formData.get("useWallet") !== "0";
274	  const taxCtx = await taxContextForUser(user);
275	  const taxOn = (netCents: number) => Math.round((netCents * taxCtx.ratePercent) / 100);
276	  const dueWithTax = (netCents: number) => netCents + taxOn(netCents);
277	  let { cardCents } = walletSplit({ dueCents: dueWithTax(quote.chargeCents), balanceCents: user.balanceCents, useWallet });
278	
279	  if (cardCents <= 0) {
280	    return { error: "Your wallet balance already covers this order — deploy it from the Review step without a card." };
281	  }
282	
283	  let promoReservationToken: string | null = null;
284	  let couponReservationToken: string | null = null;
285	  let checkoutIntent = intent;
286	
287	  if (quote.promoCreditCents > 0) {
288	    const reservedUntil = new Date(Date.now() + PAYPAL_HOLD_MS);
289	    const res = await reserveFirstMonthFree({
290	      userId: user.id,
291	      ipHash: promoIpHash,
292	      serviceType: "VPS",
293	      campaign: promoCampaign,
294	      chargedCents: quote.chargeCents,
295	      reservedUntil,
296	    });
297	    if (res.reserved) {
298	      promoReservationToken = res.token;
299	    } else {
300	      quote = await orderQuote(intent, { suppressPromo: true });
301	      ({ cardCents } = walletSplit({ dueCents: dueWithTax(quote.chargeCents), balanceCents: user.balanceCents, useWallet }));
302	      if (cardCents <= 0) {
303	        return { error: "Your wallet balance already covers this order at full price — deploy it from the Review step." };
304	      }
305	    }
306	  }
307	
308	  if (quote.couponId && quote.couponDiscountCents > 0) {
309	    const reservedUntil = new Date(Date.now() + PAYPAL_HOLD_MS);
310	    const res = await reserveOrderCoupon({
311	      couponId: quote.couponId,
312	      maxRedemptions: quote.couponMaxRedemptions,
313	      firstTimeOnly: quote.couponFirstTimeOnly,
314	      userId: user.id,
315	      ipHash: promoIpHash,
316	      amountCents: quote.couponDiscountCents,
317	      reservedUntil,
318	    });
319	    if (res.reserved) {
320	      couponReservationToken = res.token;
321	    } else {
322	      checkoutIntent = { ...intent, couponCode: undefined };
323	      quote = await orderQuote(checkoutIntent, { suppressPromo: !promoReservationToken });
324	      ({ cardCents } = walletSplit({ dueCents: dueWithTax(quote.chargeCents), balanceCents: user.balanceCents, useWallet }));
325	    }
326	  }
327	
328	  const release = async () => {
329	    if (promoReservationToken) await releaseReservation(promoReservationToken).catch(() => {});
330	    if (couponReservationToken) await releaseOrderCouponReservation(couponReservationToken).catch(() => {});
331	  };
332	
333	  const slim: OrderIntent = { ...checkoutIntent, sshPublicKey: undefined, sshKeyName: undefined };
334	  const sold: OrderPrice = orderPriceOf(quote, { taxCents: taxOn(quote.chargeCents), ratePercent: taxCtx.ratePercent, country: taxCtx.country });
335	  const metadata: Record<string, string> = {
336	    nxeonUserId: user.id,
337	    nxeonOrder: packExternalPaymentMetadata("Order intent", slim),
338	    nxeonOrderPrice: packExternalPaymentMetadata("Order price", sold),
339	    nxeonPromoCampaign: promoCampaign ?? "",
340	    ...(promoReservationToken ? { nxeonPromoReservation: promoReservationToken } : {}),
341	    ...(couponReservationToken ? { nxeonCouponReservation: couponReservationToken } : {}),
342	  };
343	
344	  return { cardCents, metadata, release };
345	}
346	
347	export async function createOrderPayPalOrder(formData: FormData): Promise<CreatePayPalOrderResult> {
348	  const user = await requireUser();
349	  const quoted = await quoteVpsOrderForExternalPayment(formData);
350	  if ("error" in quoted) return quoted;
351	  const result = await openPayPal({
352	    userId: user.id,
353	    kind: "order",
354	    amountCents: quoted.cardCents,
355	    metadata: quoted.metadata,
356	    description: "Nxeon VPS order",
357	  });
358	  if ("error" in result) await quoted.release();
359	  return result;
360	}
