362	export async function createOrderCoinbaseCharge(formData: FormData): Promise<CreateCoinbaseChargeResult> {
363	  const user = await requireUser();
364	  const quoted = await quoteVpsOrderForExternalPayment(formData);
365	  if ("error" in quoted) return quoted;
366	  const result = await openCoinbase({
367	    userId: user.id,
368	    kind: "order",
369	    amountCents: quoted.cardCents,
370	    metadata: quoted.metadata,
371	    name: "Nxeon VPS",
372	    description: "Nxeon VPS order",
373	    redirectPath: "/dashboard/deploy?paid=1",
374	    cancelPath: "/dashboard/deploy?product=vps",
375	  });
376	  if ("error" in result) await quoted.release();
377	  return result;
378	}
