380	/* ------------------------------------------------------------------ *
381	 * Game-server order — mirrors payAndDeployGame (no promo/coupon/VAT for game).
382	 * ------------------------------------------------------------------ */
383	
384	async function quoteGameOrderForExternalPayment(
385	  formData: FormData,
386	): Promise<{ error: string } | { cardCents: number; metadata: Record<string, string> }> {
387	  const user = await requireUser();
388	  await assertNotImpersonating();
389	  const unverified = await emailVerificationError(user);
390	  if (unverified) return { error: unverified };
391	  const gateErr = await gameOrderGate(user);
392	  if (gateErr) return { error: gateErr };
393	
394	  const intent = gameIntentFromFormData(formData);
395	  let quote;
396	  try {
397	    quote = await gameOrderQuote(intent);
398	  } catch (e) {
399	    if (e instanceof GameOrderError) return { error: e.message };
400	    throw e;
401	  }
402	  const chargeCents = quote.chargeCents;
403	  const useWallet = formData.get("useWallet") !== "0";
404	  const { cardCents } = walletSplit({ dueCents: chargeCents, balanceCents: user.balanceCents, useWallet });
405	  if (cardCents <= 0) {
406	    return { error: "Your wallet balance already covers this order — deploy it from the Review step without a card." };
407	  }
408	
409	  const sold: GameOrderPrice = { chargeCents };
410	  const slim = {
411	    gamePlanId: intent.gamePlanId,
412	    termMonths: intent.termMonths,
413	    serverName: intent.serverName,
414	    hostname: intent.hostname,
415	    variant: intent.variant,
416	  };
417	  const configJson = intent.config ? JSON.stringify(intent.config) : "";
418	  const carryConfig = configJson !== "" && configJson.length <= 480;
419	  const metadata: Record<string, string> = {
420	    nxeonUserId: user.id,
421	    nxeonGameOrder: packExternalPaymentMetadata("Game order intent", slim),
422	    nxeonGameOrderPrice: packExternalPaymentMetadata("Game order price", sold),
423	    ...(carryConfig ? { nxeonGameConfig: configJson } : {}),
424	  };
425	  return { cardCents, metadata };
426	}
