451	/* ------------------------------------------------------------------ *
452	 * Shared-hosting order — mirrors placeHostingOrder's first-month-free path
453	 * (lib/actions-hosting.ts), no coupon/VAT.
454	 * ------------------------------------------------------------------ */
455	
456	export type HostingExternalInput = {
457	  planId: string;
458	  domain?: string;
459	  subdomainLabel?: string;
460	  extraDiskGB?: number;
461	  termMonths?: number;
462	  appSlug?: string;
463	  idempotencyKey: string;
464	  useWallet?: boolean;
465	};
466	
467	async function quoteHostingOrderForExternalPayment(
468	  input: HostingExternalInput,
469	): Promise<{ error: string } | { cardCents: number; metadata: Record<string, string> }> {
470	  const user = await requireUser();
471	  await assertNotImpersonating();
472	  const unverified = await emailVerificationError(user);
473	  if (unverified) return { error: unverified };
474	
475	  const key = String(input.idempotencyKey ?? "").trim();
476	  if (!/^[A-Za-z0-9_-]{8,64}$/.test(key)) return { error: "Couldn't start the order — please reload and try again." };
477	
478	  const partnerSource = partnerSourceFromCookie(await cookies());
479	  const term = normalizeProductTerm(input.termMonths);
480	  const plan = await db.hostingPlan.findUnique({ where: { id: input.planId } });
481	  if (!plan || !plan.active) return { error: "That hosting plan isn't available." };
482	  const extraGB = normalizeExtraDiskAddGB(input.extraDiskGB);
483	
484	  const promoEnabled = firstMonthFreeAppliesTo("HOSTING") && (await firstMonthFreeEnabled());
485	  const ipHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
486	  const { fullCharge, promoCharge } = await hostingChargeCents(plan, term, extraGB);
487	  const eligible = promoEnabled && (await firstMonthFreeEligible(user.id, ipHash));
488	  const dueTodayCents = eligible ? promoCharge : fullCharge;
489	  const useWallet = input.useWallet !== false;
490	  const { cardCents } = walletSplit({ dueCents: dueTodayCents, balanceCents: user.balanceCents, useWallet });
491	  if (cardCents <= 0) {
492	    return { error: "Your wallet balance already covers this order — deploy it from the Review step without a card." };
493	  }
494	
495	  const intent = {
496	    planId: input.planId,
497	    domain: input.domain,
498	    subdomainLabel: input.subdomainLabel,
499	    extraDiskGB: extraGB || undefined,
500	    termMonths: term,
501	    appSlug: input.appSlug,
502	    idempotencyKey: key,
503	    partnerSource,
504	  };
505	  const metadata: Record<string, string> = {
506	    nxeonUserId: user.id,
507	    nxeonHostOrder: packExternalPaymentMetadata("Hosting order intent", intent),
508	  };
509	  return { cardCents, metadata };
510	}
