546	const EMAIL_DOMAIN_RE = /^(?=.{1,253}$)([a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,}$/i;
547	
548	async function quoteEmailOrderForExternalPayment(
549	  input: EmailExternalInput,
550	): Promise<{ error: string } | { cardCents: number; metadata: Record<string, string> }> {
551	  const user = await requireUser();
552	  await assertNotImpersonating();
553	  const unverified = await emailVerificationError(user);
554	  if (unverified) return { error: unverified };
555	
556	  const name = String(input.domainName ?? "").trim().toLowerCase().replace(/\.$/, "");
557	  if (!name) return { error: "Enter a domain." };
558	  if (!EMAIL_DOMAIN_RE.test(name)) return { error: "Enter a valid domain (e.g. example.com)." };
559	
560	  const plan = await db.emailPlan.findUnique({ where: { id: input.emailPlanId } });
561	  if (!plan || !plan.active) return { error: "That email plan isn't available." };
562	  const term = normalizeProductTerm(input.termMonths);
563	  const { fullCharge } = await emailChargeCents(plan, term);
564	  const useWallet = input.useWallet !== false;
565	  const { cardCents } = walletSplit({ dueCents: fullCharge, balanceCents: user.balanceCents, useWallet });
566	  if (cardCents <= 0) {
567	    return { error: "Your wallet balance already covers this order — deploy it from the Review step without a card." };
568	  }
569	
570	  const dupe = await db.emailSubscription.findFirst({ where: { domainName: name, status: { not: "CANCELLED" } } });
571	  if (dupe) {
572	    return {
573	      error:
574	        dupe.userId === user.id
575	          ? "This domain already has an email subscription."
576	          : "That domain is already set up for email on Nxeon. If it belongs to you, contact support and we'll verify ownership and move it across.",
577	    };
578	  }
579	
580	  const metadata: Record<string, string> = {
581	    nxeonUserId: user.id,
582	    nxeonEmailOrder: packExternalPaymentMetadata("Email order intent", { domainName: name, emailPlanId: input.emailPlanId, termMonths: term }),
583	  };
584	  return { cardCents, metadata };
585	}
