113	/**
114	 * A short, collision-avoiding suffix (3–4 lowercase base36 chars) for the default
115	 * hostname. Browser runtime, display-only — `Math.random` is fine here. The regex
116	 * strip + `padEnd` guarantee the result is [a-z0-9] and at least 3 chars, so the
117	 * hostname built from it always satisfies `hostnameValid`.
118	 */
119	function randHostSuffix() {
120	  return Math.random().toString(36).replace(/[^a-z0-9]/g, "").slice(0, 4).padEnd(3, "0");
