122	/**
123	 * A friendly, always-valid default hostname derived from the chosen image family
124	 * plus `suffix` — e.g. "ubuntu-0k4f", "debian-9c1". Lowercase, starts with a
125	 * letter/digit, contains no leading/trailing hyphen, so it passes `hostnameValid`
126	 * out of the box and a first-timer never has to invent a name to move on.
127	 */
128	function defaultHostnameFor(image: Image | undefined, suffix: string) {
