411	export type HostingOrderInput = {
412	  planId: string;
413	  /** Empty/omitted => a free `<label|username>.<base>` subdomain (see subdomainLabel). */
414	  domain?: string;
415	  /** Customer-chosen free-subdomain label (used only when `domain` is empty). */
416	  subdomainLabel?: string;
417	  /** Optional extra storage (GB) bought at deploy, on top of the plan allowance. */
418	  extraDiskGB?: number;
419	  termMonths?: number;
420	  /** Optional catalog app to auto-install after the account provisions. */
421	  appSlug?: string;
422	  /** Client-generated token that makes a resubmit a no-op (double-submit guard). */
423	  idempotencyKey: string;
